// Regenerate the browser bundle from the editable script directory.
const fs=require('fs'),path=require('path');
const dir=path.join(__dirname,'chrome_extension','js代码');
const scripts=Object.fromEntries(fs.readdirSync(dir).filter(n=>n.endsWith('.js')).map(n=>[n,fs.readFileSync(path.join(dir,n),'utf8')]));
const overlay={name:'444_品牌服务叠加图.jpg',value:'data:image/jpeg;base64,'+fs.readFileSync(path.join(__dirname,'项目素材','444叠加图','444_品牌服务叠加图.jpg')).toString('base64')};
fs.writeFileSync(path.join(__dirname,'custom-step-builtin-scripts.js'),
    '// Generated by node build-suite-scripts.js\nwindow.CustomStepBuiltinScripts='+JSON.stringify(scripts)+';\n'+
    'window.CustomStepBuiltinOverlay='+JSON.stringify(overlay)+';\n'+
    'for(const step of window.CustomStepDefaults)for(const script of step.postprocess||[])if(!script.code&&window.CustomStepBuiltinScripts[script.name])script.code=window.CustomStepBuiltinScripts[script.name];\n'+
    'for(const step of window.CustomStepDefaults)for(const script of step.postprocess||[])if(script.name==="444叠加后处理.js")script.resourceValues={cardImage:JSON.parse(JSON.stringify(window.CustomStepBuiltinOverlay))};\n');
